USE canadian_labour_market;
CREATE TABLE IF NOT EXISTS article (
 ArticleID INT PRIMARY KEY, Title VARCHAR(255) NOT NULL, PublicationDate DATE NOT NULL,
 DateKey INT NOT NULL, BodyText LONGTEXT NOT NULL, SourceURL VARCHAR(512) NOT NULL UNIQUE,
 RetrievedAtUTC VARCHAR(48) NOT NULL, ReviewStatus VARCHAR(60) NOT NULL,
 FOREIGN KEY (DateKey) REFERENCES dim_date(DateKey)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS article_province (
 ArticleID INT NOT NULL, ProvinceKey INT NOT NULL, PRIMARY KEY (ArticleID,ProvinceKey),
 FOREIGN KEY (ArticleID) REFERENCES article(ArticleID), FOREIGN KEY (ProvinceKey) REFERENCES dim_province(ProvinceKey)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS article_industry (
 ArticleID INT NOT NULL, IndustryKey INT NOT NULL, PRIMARY KEY (ArticleID,IndustryKey),
 FOREIGN KEY (ArticleID) REFERENCES article(ArticleID), FOREIGN KEY (IndustryKey) REFERENCES dim_industry(IndustryKey)
) ENGINE=InnoDB;
DROP TEMPORARY TABLE IF EXISTS d31_src_article, d31_src_province, d31_src_industry;
CREATE TEMPORARY TABLE d31_src_article LIKE article;
CREATE TEMPORARY TABLE d31_src_province (ArticleID INT, Code VARCHAR(10), PRIMARY KEY (ArticleID,Code));
CREATE TEMPORARY TABLE d31_src_industry (ArticleID INT, Code VARCHAR(100), PRIMARY KEY (ArticleID,Code));
