DROP PROCEDURE IF EXISTS d31_load_reviewed_articles_v1;
DELIMITER $$
CREATE PROCEDURE d31_load_reviewed_articles_v1()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
 -- Separate validations avoid MySQL 1137 (reopening a temporary table).
 IF (SELECT COUNT(*) FROM d31_src_article s JOIN dim_date d ON d.DateKey=s.DateKey) <> 3 THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expected 3 articles with matching dates';
 END IF;
 IF (SELECT COUNT(*) FROM d31_src_province s JOIN dim_province d ON d.ProvinceCode=s.Code) <> 13 THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expected 13 valid province links';
 END IF;
 IF (SELECT COUNT(*) FROM d31_src_industry s JOIN dim_industry d ON d.NAICSCode=s.Code) <> 20 THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Expected 20 valid industry links';
 END IF;
 IF EXISTS (SELECT 1 FROM d31_src_industry s WHERE
     (SELECT COUNT(*) FROM dim_industry d WHERE d.NAICSCode=s.Code) <> 1) THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ambiguous or missing industry code';
 END IF;
 IF EXISTS(SELECT 1 FROM d31_src_article s JOIN article a ON a.ArticleID=s.ArticleID OR a.SourceURL=s.SourceURL
 WHERE a.ArticleID<>s.ArticleID OR BINARY a.SourceURL<>BINARY s.SourceURL OR a.DateKey<>s.DateKey OR a.PublicationDate<>s.PublicationDate OR BINARY a.BodyText<>BINARY s.BodyText OR BINARY a.Title<>BINARY s.Title OR BINARY a.RetrievedAtUTC<>BINARY s.RetrievedAtUTC OR BINARY a.ReviewStatus<>BINARY s.ReviewStatus)
 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing article differs from the source; review before continuing.'; END IF;
 INSERT INTO article SELECT s.* FROM d31_src_article s WHERE NOT EXISTS(SELECT 1 FROM article a WHERE a.ArticleID=s.ArticleID);
 INSERT INTO article_province SELECT s.ArticleID,d.ProvinceKey FROM d31_src_province s JOIN dim_province d ON d.ProvinceCode=s.Code
 WHERE NOT EXISTS(SELECT 1 FROM article_province b WHERE b.ArticleID=s.ArticleID AND b.ProvinceKey=d.ProvinceKey);
 INSERT INTO article_industry SELECT s.ArticleID,d.IndustryKey FROM d31_src_industry s JOIN dim_industry d ON d.NAICSCode=s.Code
 WHERE NOT EXISTS(SELECT 1 FROM article_industry b WHERE b.ArticleID=s.ArticleID AND b.IndustryKey=d.IndustryKey);
 COMMIT;
END$$
DELIMITER ;
CALL d31_load_reviewed_articles_v1();
-- Keep the loader procedure so it can be inspected and reused.
-- It is only called after the staging tables have been populated in this session.
-- Grid 1: counts for the three selected articles on a clean load.
SELECT (SELECT COUNT(*) FROM article WHERE ArticleID IN (1,2,3)) AS articles,
 (SELECT COUNT(*) FROM article_province WHERE ArticleID IN (1,2,3)) AS province_links,
 (SELECT COUNT(*) FROM article_industry WHERE ArticleID IN (1,2,3)) AS industry_links;
-- Grid 2: find the Quebec release by its employment month.
SELECT p.ProvinceName,d.ReferenceMonth,a.Title,a.PublicationDate,a.SourceURL
FROM article a JOIN article_province b ON b.ArticleID=a.ArticleID JOIN dim_province p ON p.ProvinceKey=b.ProvinceKey
JOIN dim_date d ON d.DateKey=a.DateKey WHERE p.ProvinceCode='QC' AND a.DateKey=202002;
-- Grid 3: find an article by industry.
SELECT i.IndustryLabel,a.Title,a.SourceURL FROM article a JOIN article_industry b ON b.ArticleID=a.ArticleID
JOIN dim_industry i ON i.IndustryKey=b.IndustryKey WHERE i.NAICSCode='23' AND a.DateKey=202004;
-- Grid 4: demonstrate a safe contextual filter with EXISTS, never multiplying a fact row.
WITH sample AS (SELECT f.* FROM fact_employment f JOIN dim_province p ON p.ProvinceKey=f.ProvinceKey
 JOIN dim_industry i ON i.IndustryKey=f.IndustryKey WHERE f.DateKey=202002 AND p.ProvinceCode='QC' AND i.NAICSCode='31-33')
SELECT COUNT(*) AS rows_before, SUM(EmploymentValueThousands) AS employment_before,
 (SELECT COUNT(*) FROM sample f WHERE EXISTS(SELECT 1 FROM article a JOIN article_province b ON b.ArticleID=a.ArticleID
 WHERE a.DateKey=f.DateKey AND b.ProvinceKey=f.ProvinceKey)) AS rows_with_article,
 (SELECT SUM(f.EmploymentValueThousands) FROM sample f WHERE EXISTS(SELECT 1 FROM article a JOIN article_province b ON b.ArticleID=a.ArticleID
 WHERE a.DateKey=f.DateKey AND b.ProvinceKey=f.ProvinceKey)) AS employment_with_article FROM sample;


-- GRID 5: human-readable article overview
SELECT ArticleID, Title, DateKey AS ReferenceMonth, PublicationDate,
       ReviewStatus, SourceURL, CHAR_LENGTH(BodyText) AS TextCharacters
FROM article WHERE ArticleID IN (1,2,3) ORDER BY ArticleID;

-- GRID 6: read province tags (compare with article_tags_review.csv evidence)
SELECT a.ArticleID, a.Title, p.ProvinceCode, p.ProvinceName
FROM article a JOIN article_province ap ON ap.ArticleID=a.ArticleID
JOIN dim_province p ON p.ProvinceKey=ap.ProvinceKey
WHERE a.ArticleID IN (1,2,3) ORDER BY a.ArticleID,p.ProvinceCode;

-- GRID 7: read industry tags (compare with article_tags_review.csv evidence)
SELECT a.ArticleID, a.Title, i.NAICSCode, i.IndustryLabel
FROM article a JOIN article_industry ai ON ai.ArticleID=a.ArticleID
JOIN dim_industry i ON i.IndustryKey=ai.IndustryKey
WHERE a.ArticleID IN (1,2,3) ORDER BY a.ArticleID,i.NAICSCode;

-- GRID 8: readable article text sample (no hex)
SELECT ArticleID, Title, LEFT(BodyText,1200) AS ArticleExcerpt
FROM article WHERE ArticleID IN (1,2,3) ORDER BY ArticleID;

-- GRID 9: confirm employment fact count was not changed by loader
SELECT COUNT(*) AS fact_employment_rows FROM fact_employment;
